#include "sqlite_repository.hpp"
#include "../persistence/transaction.hpp"
#include <stdexcept>
namespace exotic::autonomy::governance {using persistence::Statement;using persistence::Transaction;
SqliteGovernanceRepository::SqliteGovernanceRepository(const std::filesystem::path&p):db_(p){migrate();}
void SqliteGovernanceRepository::migrate(){db_.execute("CREATE TABLE IF NOT EXISTS governance_requests(id INTEGER PRIMARY KEY,proposal_id INTEGER NOT NULL,requester_id TEXT NOT NULL,action TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT NOT NULL,risk TEXT NOT NULL,requested_autonomy INTEGER NOT NULL,requested_budget REAL NOT NULL,required_approvals INTEGER NOT NULL,require_distinct_roles INTEGER NOT NULL,simulation_only INTEGER NOT NULL,status TEXT NOT NULL,created_at_ms INTEGER NOT NULL,expires_at_ms INTEGER NOT NULL,decided_at_ms INTEGER);CREATE TABLE IF NOT EXISTS governance_decisions(id INTEGER PRIMARY KEY,request_id INTEGER NOT NULL,approver_id TEXT NOT NULL,approver_role TEXT NOT NULL,vote TEXT NOT NULL,reason TEXT NOT NULL,created_at_ms INTEGER NOT NULL);CREATE UNIQUE INDEX IF NOT EXISTS governance_decision_unique ON governance_decisions(request_id,approver_id);CREATE TABLE IF NOT EXISTS governance_grants(id INTEGER PRIMARY KEY,subject_id TEXT NOT NULL,action TEXT NOT NULL,resource_type TEXT NOT NULL,scope TEXT NOT NULL,maximum_autonomy INTEGER NOT NULL,budget_limit REAL NOT NULL,valid_from_ms INTEGER NOT NULL,valid_until_ms INTEGER,revoked INTEGER NOT NULL,granted_by TEXT NOT NULL);CREATE TABLE IF NOT EXISTS governance_policies(id INTEGER PRIMARY KEY,name TEXT NOT NULL,version INTEGER NOT NULL,active INTEGER NOT NULL,created_at_ms INTEGER NOT NULL,rules_blob TEXT NOT NULL);CREATE TABLE IF NOT EXISTS governance_evidence(id INTEGER PRIMARY KEY,request_id INTEGER NOT NULL,event_type TEXT NOT NULL,actor TEXT NOT NULL,payload_json TEXT NOT NULL,previous_hash TEXT NOT NULL,hash TEXT NOT NULL UNIQUE,created_at_ms INTEGER NOT NULL);CREATE TABLE IF NOT EXISTS governance_control(singleton INTEGER PRIMARY KEY CHECK(singleton=1),emergency_stop INTEGER NOT NULL,actor TEXT NOT NULL,reason TEXT NOT NULL,updated_at_ms INTEGER NOT NULL);INSERT OR IGNORE INTO governance_control VALUES(1,0,'system','',0);");}
std::uint64_t SqliteGovernanceRepository::next(std::string_view t){return db_.next_sequence("governance."+std::string{t});}ApprovalRequestId SqliteGovernanceRepository::next_request_id(){return next("governance_requests");}DecisionId SqliteGovernanceRepository::next_decision_id(){return next("governance_decisions");}GrantId SqliteGovernanceRepository::next_grant_id(){return next("governance_grants");}PolicyId SqliteGovernanceRepository::next_policy_id(){return next("governance_policies");}EvidenceId SqliteGovernanceRepository::next_evidence_id(){return next("governance_evidence");}
void SqliteGovernanceRepository::save_request(const ApprovalRequest&r){Statement s{db_,"INSERT INTO governance_requests VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET status=excluded.status,decided_at_ms=excluded.decided_at_ms"};s.bind(1,(std::int64_t)r.id);s.bind(2,(std::int64_t)r.proposal_id);s.bind(3,r.requester_id);s.bind(4,r.action);s.bind(5,r.resource.type);s.bind(6,r.resource.id);s.bind(7,to_string(r.risk));s.bind(8,(std::int64_t)r.requested_autonomy);s.bind(9,r.requested_budget_usd);s.bind(10,(std::int64_t)r.required_approvals);s.bind(11,(std::int64_t)r.require_distinct_roles);s.bind(12,(std::int64_t)r.simulation_only);s.bind(13,to_string(r.status));s.bind(14,to_unix_milliseconds(r.created_at));s.bind(15,to_unix_milliseconds(r.expires_at));if(r.decided_at)s.bind(16,to_unix_milliseconds(*r.decided_at));else s.bind_null(16);s.execute();}
std::optional<ApprovalRequest> SqliteGovernanceRepository::load_request(ApprovalRequestId id){Statement s{db_,"SELECT proposal_id,requester_id,action,resource_type,resource_id,risk,requested_autonomy,requested_budget,required_approvals,require_distinct_roles,simulation_only,status,created_at_ms,expires_at_ms,decided_at_ms FROM governance_requests WHERE id=?"};s.bind(1,(std::int64_t)id);if(!s.step())return{};ApprovalRequest r;r.id=id;r.proposal_id=s.column_int64(0);r.requester_id=s.column_text(1);r.action=s.column_text(2);r.resource={s.column_text(3),s.column_text(4),{}};r.risk=risk_from_string(s.column_text(5)).value_or(RiskLevel::Critical);r.requested_autonomy=(AutonomyLevel)s.column_int64(6);r.requested_budget_usd=s.column_double(7);r.required_approvals=s.column_int64(8);r.require_distinct_roles=s.column_int64(9)!=0;r.simulation_only=s.column_int64(10)!=0;r.status=approval_status_from_string(s.column_text(11)).value_or(ApprovalStatus::Rejected);r.created_at=from_unix_milliseconds(s.column_int64(12));r.expires_at=from_unix_milliseconds(s.column_int64(13));if(!s.column_is_null(14))r.decided_at=from_unix_milliseconds(s.column_int64(14));return r;}
std::vector<ApprovalRequest> SqliteGovernanceRepository::load_pending(TimePoint){std::vector<ApprovalRequest>v;Statement s{db_,"SELECT id FROM governance_requests WHERE status='pending' ORDER BY id"};while(s.step())if(auto r=load_request(s.column_int64(0)))v.push_back(*r);return v;}
void SqliteGovernanceRepository::append_decision(const ApprovalDecision&d){Statement s{db_,"INSERT INTO governance_decisions VALUES(?,?,?,?,?,?,?)"};s.bind(1,(std::int64_t)d.id);s.bind(2,(std::int64_t)d.request_id);s.bind(3,d.approver_id);s.bind(4,d.approver_role);s.bind(5,to_string(d.vote));s.bind(6,d.reason);s.bind(7,to_unix_milliseconds(d.created_at));s.execute();}
std::vector<ApprovalDecision> SqliteGovernanceRepository::load_decisions(ApprovalRequestId id){std::vector<ApprovalDecision>v;Statement s{db_,"SELECT id,approver_id,approver_role,vote,reason,created_at_ms FROM governance_decisions WHERE request_id=? ORDER BY id"};s.bind(1,(std::int64_t)id);while(s.step()){ApprovalDecision d;d.id=s.column_int64(0);d.request_id=id;d.approver_id=s.column_text(1);d.approver_role=s.column_text(2);d.vote=vote_from_string(s.column_text(3)).value_or(Vote::Abstain);d.reason=s.column_text(4);d.created_at=from_unix_milliseconds(s.column_int64(5));v.push_back(d);}return v;}
void SqliteGovernanceRepository::save_grant(const CapabilityGrant&g){Statement s{db_,"INSERT OR REPLACE INTO governance_grants VALUES(?,?,?,?,?,?,?,?,?,?,?)"};s.bind(1,(std::int64_t)g.id);s.bind(2,g.subject_id);s.bind(3,g.capability.action);s.bind(4,g.capability.resource_type);s.bind(5,g.capability.scope);s.bind(6,(std::int64_t)g.maximum_autonomy);s.bind(7,g.budget_limit_usd);s.bind(8,to_unix_milliseconds(g.valid_from));if(g.valid_until)s.bind(9,to_unix_milliseconds(*g.valid_until));else s.bind_null(9);s.bind(10,(std::int64_t)g.revoked);s.bind(11,g.granted_by);s.execute();}
std::vector<CapabilityGrant> SqliteGovernanceRepository::load_grants(std::string_view id){std::vector<CapabilityGrant>v;Statement s{db_,"SELECT id,action,resource_type,scope,maximum_autonomy,budget_limit,valid_from_ms,valid_until_ms,revoked,granted_by FROM governance_grants WHERE subject_id=?"};s.bind(1,id);while(s.step()){CapabilityGrant g;g.id=s.column_int64(0);g.subject_id=std::string(id);g.capability={s.column_text(1),s.column_text(2),s.column_text(3)};g.maximum_autonomy=(AutonomyLevel)s.column_int64(4);g.budget_limit_usd=s.column_double(5);g.valid_from=from_unix_milliseconds(s.column_int64(6));if(!s.column_is_null(7))g.valid_until=from_unix_milliseconds(s.column_int64(7));g.revoked=s.column_int64(8)!=0;g.granted_by=s.column_text(9);v.push_back(g);}return v;}
void SqliteGovernanceRepository::save_policy(const PolicyVersion&p){std::string blob;for(const auto&r:p.rules)blob+=r.id+"|"+to_string(r.effect)+"|"+r.action+"|"+r.resource_type+"|"+r.required_role+"|"+r.attribute_key+"|"+r.attribute_value+"|"+std::to_string((int)r.minimum_risk)+"|"+std::to_string(r.simulation_only)+"\n";Statement s{db_,"INSERT OR REPLACE INTO governance_policies VALUES(?,?,?,?,?,?)"};s.bind(1,(std::int64_t)p.id);s.bind(2,p.name);s.bind(3,(std::int64_t)p.version);s.bind(4,(std::int64_t)p.active);s.bind(5,to_unix_milliseconds(p.created_at));s.bind(6,blob);s.execute();}
std::vector<PolicyVersion> SqliteGovernanceRepository::load_active_policies(){std::vector<PolicyVersion>v;Statement s{db_,"SELECT id,name,version,created_at_ms,rules_blob FROM governance_policies WHERE active=1"};while(s.step()){PolicyVersion p;p.id=s.column_int64(0);p.name=s.column_text(1);p.version=s.column_int64(2);p.created_at=from_unix_milliseconds(s.column_int64(3));std::string blob=s.column_text(4);std::size_t pos=0;while(pos<blob.size()){auto end=blob.find('\n',pos);auto line=blob.substr(pos,end==std::string::npos?std::string::npos:end-pos);if(!line.empty()){std::vector<std::string> f;std::size_t q=0;while(q<=line.size()){auto z=line.find('|',q);f.push_back(line.substr(q,z==std::string::npos?std::string::npos:z-q));if(z==std::string::npos)break;q=z+1;}if(f.size()==9){PolicyRule r;r.id=f[0];r.effect=f[1]=="allow"?Effect::Allow:(f[1]=="escalate"?Effect::Escalate:Effect::Deny);r.action=f[2];r.resource_type=f[3];r.required_role=f[4];r.attribute_key=f[5];r.attribute_value=f[6];r.minimum_risk=(RiskLevel)std::stoi(f[7]);r.simulation_only=f[8]=="1";p.rules.push_back(std::move(r));}}if(end==std::string::npos)break;pos=end+1;}v.push_back(p);}return v;}
void SqliteGovernanceRepository::append_evidence(const DecisionEvidence&e){Statement s{db_,"INSERT INTO governance_evidence VALUES(?,?,?,?,?,?,?,?)"};s.bind(1,(std::int64_t)e.id);s.bind(2,(std::int64_t)e.request_id);s.bind(3,e.event_type);s.bind(4,e.actor);s.bind(5,e.payload_json);s.bind(6,e.previous_hash);s.bind(7,e.hash);s.bind(8,to_unix_milliseconds(e.created_at));s.execute();}
std::vector<DecisionEvidence> SqliteGovernanceRepository::load_evidence(ApprovalRequestId id){std::vector<DecisionEvidence>v;Statement s{db_,"SELECT id,event_type,actor,payload_json,previous_hash,hash,created_at_ms FROM governance_evidence WHERE request_id=? ORDER BY id"};s.bind(1,(std::int64_t)id);while(s.step()){DecisionEvidence e;e.id=s.column_int64(0);e.request_id=id;e.event_type=s.column_text(1);e.actor=s.column_text(2);e.payload_json=s.column_text(3);e.previous_hash=s.column_text(4);e.hash=s.column_text(5);e.created_at=from_unix_milliseconds(s.column_int64(6));v.push_back(e);}return v;}
void SqliteGovernanceRepository::set_emergency_stop(bool on,std::string_view a,std::string_view r){Statement s{db_,"UPDATE governance_control SET emergency_stop=?,actor=?,reason=?,updated_at_ms=? WHERE singleton=1"};s.bind(1,(std::int64_t)on);s.bind(2,a);s.bind(3,r);s.bind(4,to_unix_milliseconds(Clock::now()));s.execute();}bool SqliteGovernanceRepository::emergency_stop_active(){Statement s{db_,"SELECT emergency_stop FROM governance_control WHERE singleton=1"};return s.step()&&s.column_int64(0)!=0;}
}
